var aiUi=require("$:/plugins/huwiki/ai/i18n.js");
/*\
title: $:/plugins/huwiki/ai/connection-status-widget.js
type: application/javascript
module-type: widget

Connection onboarding: public metadata only, never API keys.\*/
(function(){
"use strict";
var consent=require("$:/plugins/huwiki/ai/consent.js");
var Widget=require("$:/core/modules/widgets/widget.js").widget;
var adapters=require("$:/plugins/huwiki/ai/model-adapters.js");
var manual=require("$:/plugins/huwiki/ai/manual-connections.js");
var KEY="huwiki-ai-settings-v0.1";
function settings(){try{return JSON.parse(window.localStorage.getItem(KEY)||"{}");}catch(e){return {};}}
function save(v){try{window.localStorage.setItem(KEY,JSON.stringify(v));window.dispatchEvent(new Event("huwiki-ai-connection-change"));}catch(e){}}
function node(parent,name,klass,txt){var e=parent.ownerDocument.createElement(name);if(klass)e.className=klass;if(txt!==undefined)e.textContent=txt;parent.appendChild(e);return e;}
function button(parent,label,fn){var el=node(parent,"button","huwiki-ai-button",label);el.type="button";el.addEventListener("click",fn);return el;}
var bridge=require("$:/plugins/huwiki/ai/forgeshare.js");
function rpc(name,arg){return bridge.rpc(name,arg);}
function openVault(){bridge.pair().catch(function(err){window.alert(err.message);});}
function W(n,o){this.initialise(n,o);}W.prototype=new Widget();
W.prototype.execute=function(){};
W.prototype.render=function(parent,next){this.computeAttributes();if(aiUi.reuseWidget(this,parent,next,"connection-status-widget.js"))return;this.parentDomNode=parent;this.execute();this.root=this.document.createElement("div");this.root.className="huw-ai-connection-status";parent.insertBefore(this.root,next);this.domNodes=[this.root];this.connections=[];this.loaded=false;this.error="";this.vaultError="";this.validated="";this.answer=null;this.testing=false;this.connectionTestBusy=false;this.connectionTestId="";this.connectionTestMessage="";this.connectionTestError=false;this.manualModels={};this.manualMessage="";this.manualError=false;this.manualBusy=false;this.draw();this.refreshVault();};
W.prototype.refresh=function(changedAiLanguage){if(changedAiLanguage&&changedAiLanguage["$:/language"]){this.draw();return true;}if(this._aiUiDelegate)return this._aiUiDelegate.refresh(changedAiLanguage);return false;};
W.prototype.refreshVault=function(){var self=this;rpc("huPrivateVaultList").then(function(x){
 self.connections=(x&&Array.isArray(x.connections)?x.connections:[]).filter(function(c){return c&&c.id;});self.loaded=true;
 var s=settings();if(self.connections.length&&s.connectionMode!=="manual"&&(!s.vaultId||!self.connections.some(function(c){return c.id===s.vaultId;}))){s.vaultId=self.connections[0].id;s.connectionMode="vault";s.vaultModels=s.vaultModels||{};save(s);}
 self.draw();
}).catch(function(e){self.loaded=true;self.vaultError=String(e.message||e);self.draw();});};
W.prototype.testAnswer=function(connection,model){
  if(this.testing)return;
  if(!model){this.error=aiUi.text("Vælg først en model i chatten.");this.draw();return;}
  var approval=consent.approve(Object.assign({},connection,{model:model}),{da:aiUi.text('Kun testbeskeden: Svar kun med ordet Klar. Ingen tiddlere.'),en:'Only the test prompt: Reply with the word Ready. No tiddlers.'});
  if(!approval)return;
  var self=this,id=connection.id;
  this.testing=true;this.answer=null;this.error="";this.draw();
  rpc("huPrivateVaultAiGenerate",{
    consent:approval,connectionId:id,model:model,mode:"chat",
    messages:[{role:"user",content:aiUi.text("Svar kun med ordet Klar.")}]
  }).then(function(result){
    if(settings().vaultId!==id)return;
    if(!result||!result.ok||!String(result.content||"").trim())throw Error(aiUi.text("Modellen returnerede et tomt svar."));
    self.answer={id:id,model:model,text:String(result.content).slice(0,300)};
  }).catch(function(error){
    if(settings().vaultId===id)self.error=aiUi.text("AI-svaret kunne ikke hentes: ")+(error.message||error);
  }).then(function(){self.testing=false;self.draw();});
};

function field(parent,label,value,fn,placeholder){
 var wrap=node(parent,"label","huwiki-ai-field");
 node(wrap,"span","huwiki-ai-label",label);
 var control=node(wrap,"input","huwiki-ai-input");
 control.type="text";control.value=value||"";control.placeholder=placeholder||"";
 control.addEventListener("input",function(){fn(control.value);});
 return control;
}
function option(select,value,label){
 var o=node(select,"option",null,label);o.value=value;return o;
}
function keepAutofilledKey(box,p){
 var input=box.querySelector('input[name="huwiki-ai-key-'+p+'"]');
 if(input&&input.value&&input.value!==manual.getKey(p))manual.setKey(p,input.value);
}
function manualUrl(p,s){
 return p==="lmstudio"?(s.lmstudioUrl||"http://127.0.0.1:1234"):
        p==="ollama"?(s.ollamaUrl||"http://127.0.0.1:11434"):"";
}
W.prototype.renderManual=function(root,s,active){
 var self=this,p=manual.known(s.provider)&&s.provider!=="demo"?s.provider:"openai";
 if(s.provider!==p){s.provider=p;save(s);}
 node(root,"p","huwiki-ai-help",aiUi.choose(
  "Brug AI Forge uden ForgeShare. Vælg AI, indtast din nøgle eller lokale serveradresse, og hent modeller.",
  "Use AI Forge without ForgeShare. Choose AI, enter your key or local server address, and fetch models."
 ));
 var box=node(root,"div","huw-ai-connection-fix");
 var label=node(box,"label","huwiki-ai-field");
 node(label,"span","huwiki-ai-label",aiUi.choose("1. AI-udbyder","1. AI provider"));
 var providers=node(label,"select","huwiki-ai-input");
 [["openai","OpenAI"],["claude","Claude"],["gemini","Google Gemini"],["lmstudio","LM Studio"],["ollama","Ollama"]].forEach(function(pair){
   option(providers,pair[0],pair[1]);
 });
 providers.value=p;
 providers.addEventListener("change",function(){
   var next=settings();next.connectionMode="manual";next._manualChosen=true;next.provider=providers.value;
   save(next);self.manualMessage="";self.draw();
 });
 if(!manual.cloud(p)){
   field(box,aiUi.choose("2. Adresse til lokal AI-server","2. Local AI server address"),manualUrl(p,s),function(v){
     var next=settings();next[p+"Url"]=v.trim();save(next);
   },p==="lmstudio"?"http://127.0.0.1:1234":"http://127.0.0.1:11434");
 }else{
   node(box,"p","huwiki-ai-help",aiUi.choose(
     "2. Indtast din API-nøgle. Den gemmes ikke i wikien, og Chrome kan muligvis tilbyde autofyldning.",
     "2. Enter your API key. It is not saved in the wiki; Chrome may offer autofill."
   ));
 }
 manual.secretControl(box,p);
 var modelKey=p+"Model";
 field(box,aiUi.choose("3. Model-ID","3. Model ID"),s[modelKey]||"",function(v){
   var next=settings();next[modelKey]=v.trim();save(next);
 },aiUi.choose("Hent modeller eller indtast ID","Fetch models or enter an ID"));
 var models=this.manualModels[p]||[];
 if(models.length){
   var listLabel=node(box,"label","huwiki-ai-field");
   node(listLabel,"span","huwiki-ai-label",aiUi.choose("Vælg fundet model","Choose discovered model"));
   var select=node(listLabel,"select","huwiki-ai-input");
   models.forEach(function(name){option(select,name,name);});
   if(s[modelKey]&&models.indexOf(s[modelKey])<0)option(select,s[modelKey],s[modelKey]);
   select.value=s[modelKey]||models[0];
   select.addEventListener("change",function(){
     var next=settings();next[modelKey]=select.value;save(next);self.draw();
   });
 }
 var actions=node(box,"div","huwiki-ai-actions");
 var fetchButton=button(actions,aiUi.choose("Test / hent modeller","Test / fetch models"),function(){
   if(self.manualBusy)return;
   keepAutofilledKey(box,p);self.manualBusy=true;self.manualMessage="";self.draw();
   manual.listModels(p,manualUrl(p,settings())).then(function(names){
     self.manualModels[p]=names;
     var next=settings();
     var chosen=manual.cloud(p)?adapters.preferCloudModel(p,names,next[modelKey]):adapters.preferModel(names,next[modelKey]);
     if(chosen){next[modelKey]=chosen;save(next);}
     self.manualMessage=aiUi.choose("Forbundet · ","Connected · ")+names.length+
       aiUi.choose(" modeller fundet. Ingen tiddlere blev sendt."," models found. No tiddlers were sent.");
     self.manualError=false;
   }).catch(function(e){self.manualMessage=e.message||String(e);self.manualError=true;})
     .then(function(){self.manualBusy=false;self.draw();});
 });
 fetchButton.disabled=this.manualBusy;
 var answerButton=button(actions,aiUi.choose("Test AI-svar","Test AI response"),function(){
   if(self.manualBusy)return;
   keepAutofilledKey(box,p);
   var current=settings(),model=current[modelKey];
   if(!model){self.manualMessage=aiUi.choose("Vælg en model først.","Choose a model first.");self.manualError=true;self.draw();return;}
   try{manual.requireKey(p);}catch(err){self.manualMessage=err.message;self.manualError=true;self.draw();return;}
   var approval=consent.approve({provider:p,model:model,viaManual:true},{
     da:"Kun testbeskeden 'Svar kun med ordet Klar'. Kan bruge API-saldo. Ingen tiddlere sendes.",
     en:"Only the test prompt 'Reply only with Ready'. May use API credit. No tiddlers are sent."
   });
   if(!approval)return;
   self.manualBusy=true;self.manualMessage="";self.draw();
   manual.complete(p,manualUrl(p,current),model,[{role:"user",content:aiUi.choose("Svar kun med ordet Klar.","Reply only with Ready.")}],"chat")
     .then(function(data){self.manualMessage=aiUi.choose("AI svarede: ","AI replied: ")+String(data.text||"").slice(0,350);self.manualError=false;})
     .catch(function(err){self.manualMessage=err.message||String(err);self.manualError=true;})
     .then(function(){self.manualBusy=false;self.draw();});
 });
 answerButton.disabled=this.manualBusy;
 if(this.manualMessage)node(box,"p",this.manualError?"huw-ai-warning":"huw-ai-ready",this.manualMessage);
 button(actions,aiUi.choose("Åbn AI-chat","Open AI chat"),function(){
   self.dispatchEvent({type:"tm-navigate",navigateTo:"HUWiki AI · Chatbibliotek"});
 });
 node(box,"p","huwiki-ai-help",aiUi.choose(
  "Direkte cloud-kald er eksperimentelle og kan blokeres af CORS. Nøglen ligger kun i browserens hukommelse og kan læses af scripts på siden.",
  "Direct cloud requests are experimental and may be blocked by CORS. The key exists only in browser memory, where page scripts can read it."
 ));
 var vault=node(root,"details","huw-ai-connection-details");
 node(vault,"summary",null,aiUi.choose("ForgeShare (valgfrit alternativ)","ForgeShare (optional alternative)"));
 if(active){
   node(vault,"p","huwiki-ai-help",aiUi.choose("Der findes en godkendt ForgeShare-forbindelse.","An approved ForgeShare connection is available."));
   button(vault,aiUi.choose("Brug ForgeShare","Use ForgeShare"),function(){
     var next=settings();next.connectionMode="vault";next._manualChosen=false;next.vaultId=active.id;save(next);self.error="";self.draw();
   });
 }else{
   node(vault,"p","huwiki-ai-help",aiUi.choose(
     "Du behøver ikke ForgeShare for at bruge felterne ovenfor. Vil du bruge nøgleboksen, skal ForgeShare køre, og wikien skal åbnes via den.",
     "ForgeShare is not needed for the fields above. To use its vault, start ForgeShare and open the wiki through it."
   ));
   if(this.vaultError)node(vault,"p","huwiki-ai-muted",this.vaultError);
   button(vault,aiUi.choose("Søg efter ForgeShare","Check ForgeShare"),function(){self.vaultError="";self.refreshVault();});
   button(vault,aiUi.text("Forbind til ForgeShare"),openVault);
 }
};
W.prototype.draw=function(){var self=this,r=this.root;while(r.firstChild)r.removeChild(r.firstChild);
 consent.notice(r);
 var s=settings(),active=this.connections.find(function(c){return c.id===s.vaultId;})||this.connections[0];
 var title=node(r,"div","huw-ai-connection-title");node(title,"strong",null,aiUi.text("Din AI-forbindelse"));
 if(!active||s.connectionMode==="manual"){this.renderManual(r,s,active);return;}
 button(r,aiUi.choose("Manuel forbindelse (uden ForgeShare)","Manual connection (without ForgeShare)"),function(){var next=settings();next.connectionMode="manual";next._manualChosen=true;if(!manual.known(next.provider))next.provider="openai";save(next);self.error="";self.draw();});
 if(!this.loaded){node(r,"p",null,aiUi.text("Henter dine gemte forbindelser …"));return;}
 if(this.error){node(r,"p","huw-ai-warning",aiUi.message(this.error));button(r,aiUi.text("Prøv igen"),function(){self.error="";self.refreshVault();});}
 if(!active){node(r,"p",null,aiUi.text("Ingen gemt AI-forbindelse. Opret én for at starte en samtale."));button(r,aiUi.text("Forbind til ForgeShare"),openVault);return;}
 var row=node(r,"div","huw-ai-inline-actions"),label=node(row,"label","huw-ai-connection-picker");node(label,"span",null,aiUi.text("Vælg AI"));var select=node(label,"select","huwiki-ai-input");
 this.connections.forEach(function(c){var opt=node(select,"option",null,c.name+" · "+({gemini:"Gemini",openai:"OpenAI",claude:"Claude",ollama:"Ollama",lmstudio:"LM Studio"}[c.provider]||c.provider));opt.value=c.id;});select.value=active.id;
 select.addEventListener("change",function(){var x=settings();x.vaultId=select.value;x.connectionMode="vault";save(x);self.validated="";self.answer=null;self.error="";self.draw();});
 button(row,aiUi.text("Godkend en anden enhed"),openVault);
 var model=s.vaultModels&&s.vaultModels[active.id]||active.model||"";node(r,"p","huwiki-ai-help",model?aiUi.text("Valgt model: ")+model:aiUi.text("Vælg en model i chatten, eller test forbindelsen."));
 if(this.connectionTestBusy&&this.connectionTestId===active.id)node(r,"p","huwiki-ai-help",aiUi.choose("Tester forbindelsen via ForgeShare…","Testing the connection through ForgeShare…"));
 if(this.connectionTestMessage&&this.connectionTestId===active.id)node(r,"p",this.connectionTestError?"huw-ai-warning":"huw-ai-ready",this.connectionTestMessage);
 if(this.answer&&this.answer.id===active.id&&this.answer.model===model)node(r,"p","huw-ai-ready",aiUi.text("✓ AI svarede: ")+this.answer.text);
 if(this.testing)node(r,"p",null,aiUi.text("Venter på et AI-svar…"));
 var actions=node(r,"div","huw-ai-inline-actions");
 if(active){
   var answerButton=button(actions,aiUi.text("Test AI-svar"),function(){self.testAnswer(active,model);});
   answerButton.disabled=this.testing||this.connectionTestBusy||!model;
 }
 var connectionButton=button(actions,this.connectionTestBusy?aiUi.choose("Tester…","Testing…"):aiUi.text("Test forbindelse"),function(){
  if(self.connectionTestBusy)return;
  var id=active.id;
  self.error="";self.validated="";self.connectionTestBusy=true;self.connectionTestId=id;self.connectionTestMessage="";self.connectionTestError=false;self.draw();
  rpc("huPrivateVaultAiModels",id).then(function(d){
    if(!d||!d.ok||!Array.isArray(d.models))throw Error(d&&d.message||aiUi.choose("Ugyldigt svar fra ForgeShare.","Invalid response from ForgeShare."));
    if(settings().vaultId!==id)return;
    var models=d.models,chosen=adapters.preferCloudModel(active.provider,models,model);
    if(chosen){var x=settings();x.vaultModels=x.vaultModels||{};x.vaultModels[id]=chosen;save(x);}
    self.validated=models.length?id:"";
    self.connectionTestMessage=models.length?
      aiUi.choose("✓ Forbindelsen virker. ","✓ Connection works. ")+models.length+aiUi.choose(" modeller fundet. Valgt: "," models found. Selected: ")+chosen:
      aiUi.choose("ForgeShare svarer, men ingen modeller blev fundet hos AI-serveren.","ForgeShare responded, but no models were found on the AI server.");
    self.connectionTestError=!models.length;
  }).catch(function(e){
    if(settings().vaultId!==id)return;
    self.connectionTestMessage=aiUi.choose("Forbindelsestesten fejlede: ","Connection test failed: ")+(e.message||e);
    self.connectionTestError=true;
  }).then(function(){self.connectionTestBusy=false;self.draw();});
 });
 connectionButton.disabled=this.connectionTestBusy;
};
exports["huwiki-ai-connection-status"]=W;
})();
